    cols = len(grid[0]) if rows > 0 else 0
    result = [[0 for _ in range(cols)] for _ in range(rows)]

    # Find which rows are separator rows (all same value)
    sep_rows = set()
    for r in range(rows):
        if all(grid[r][c] == grid[r][0] for c in range(min(10, cols))):
            sep_rows.add(r)

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]

            # Skip separator rows (all 2s in demo)
            if r in sep_rows:
                # Horizontal separator: becomes 2s
                result[r][c] = 2
            else:
                # Check if this is a background cell (8 or 2 in demo)
                if val >= 8 and val <= 8:
                    # Even column position -> 8, odd -> 2
                    result[r][c] = 8 if c % 2 == 0 else 2
                elif val >= 6 and val <= 8:
                    # 6, 7, 8 are special; they get the background pattern
                    # But in output they stay as the pattern value they "should" be
                    if c % 2 == 0:
                        result[r][c] = 8
                    else:
                        result[r][c] = 2
                else:
                    # Other special values (0, 4) - preserve original
                    result[r][c] = val

    return result
