def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Identify horizontal separator rows (all 4s)
    sep_rows = set()
    for r in range(rows):
        if all(grid[r][c] == 4 for c in range(cols)):
            sep_rows.add(r)

    # Identify vertical separator columns (all 4s)
    sep_cols = set()
    for c in range(cols):
        if all(grid[r][c] == 4 for r in range(rows)):
            sep_cols.add(c)

    # Get area values for row 0 of each region
    even_pos_vals = {}
    odd_pos_vals = {}
    for r in range(rows):
        if r in sep_rows:
            continue
        # Find which region this row belongs to
        is_first = True
        for sr in sorted(sep_rows):
            if r < sr:
                is_first = True
                break
            else:
                is_first = False

        for c in range(cols):
            if c in sep_cols:
                continue
            val = grid[r][c]
            if val != 5:  # special value
                if is_first:
                    if c % 2 == 0:
                        even_pos_vals[r] = val
                    else:
                        odd_pos_vals[r] = val

    result = [[0 for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if r in sep_rows:
                result[r][c] = 4  # separator row
            elif c in sep_cols:
                result[r][c] = 4  # separator column
            else:
                if grid[r][c] != 5:  # special value exists here
                    result[r][c] = grid[r][c]
                else:
                    # Get pattern for even rows (separators become 4s)
                    # Get pattern for odd rows (separators become 2s)
                    if r % 2 == 0:
                        result[r][c] = 4 if c % 2 == 0 else 8 if c % 2 == 1 else 4
                    else:
                        result[r][c] = 4 if c % 2 == 0 else 2
                        if c % 2 != 0:
